// Density-based estimate only. Carrier rules, freight characteristics, and
// accessorials can change the final class and quote.
export const CLASS_BANDS = [
  { minDensity: 50, freightClass: 50 },
  { minDensity: 35, freightClass: 55 },
  { minDensity: 30, freightClass: 60 },
  { minDensity: 22.5, freightClass: 65 },
  { minDensity: 15, freightClass: 70 },
  { minDensity: 13.5, freightClass: 77.5 },
  { minDensity: 12, freightClass: 85 },
  { minDensity: 10.5, freightClass: 92.5 },
  { minDensity: 9, freightClass: 100 },
  { minDensity: 8, freightClass: 110 },
  { minDensity: 7, freightClass: 125 },
  { minDensity: 6, freightClass: 150 },
  { minDensity: 5, freightClass: 175 },
  { minDensity: 4, freightClass: 200 },
  { minDensity: 2, freightClass: 250 },
  { minDensity: 1, freightClass: 300 },
  { minDensity: 0.5, freightClass: 400 },
  { minDensity: 0, freightClass: 500 },
];

function positive(value, name) {
  const number = Number(value);
  if (!Number.isFinite(number) || number <= 0) throw new Error(`${name} must be greater than zero`);
  return number;
}

/**
 * The packed height at which this freight would sit exactly on `targetDensity`.
 *
 * Density is `weight * 1728 / (length * width * height)` — the piece count
 * cancels out of both halves, which is why this works on one piece and answers
 * for the whole shipment. Rearranged for height, it is the only lever in the
 * formula a shipper can usually move on the day: the weight is the goods and
 * the footprint is the pallet.
 *
 * Returns null when the target density is zero, where the height is unbounded.
 */
function heightAtDensity(weight, length, width, targetDensity) {
  if (targetDensity <= 0) return null;
  const height = weight * 1728 / (length * width * targetDensity);
  return Number.isFinite(height) ? height : null;
}

export function estimateFreightClass(input) {
  const length = positive(input.length, 'Length');
  const width = positive(input.width, 'Width');
  const height = positive(input.height, 'Height');
  const weight = positive(input.weight, 'Weight');
  const pieces = positive(input.pieces ?? 1, 'Pieces');
  if (!Number.isSafeInteger(pieces)) throw new Error('Pieces must be a whole number');
  const pieceCube = length * width * height / 1728;
  const totalCube = pieceCube * pieces;
  const totalWeight = weight * pieces;
  const density = totalWeight / totalCube;
  if (![pieceCube, totalCube, totalWeight, density].every(Number.isFinite)) {
    throw new Error('Values are too large to calculate safely');
  }
  const band = CLASS_BANDS.find(candidate => density >= candidate.minDensity);
  const bandIndex = CLASS_BANDS.indexOf(band);
  const nextBand = CLASS_BANDS[bandIndex - 1] ?? null;
  const dearerBand = CLASS_BANDS[bandIndex + 1] ?? null;

  // "You are 1.00 lb/ft³ from the next band" is true and useless: nobody ships
  // a lb/ft³. The two things a shipper can actually change on the dock are how
  // tall the pallet is packed and how much goes on it, so the gap is restated
  // in both of those units.
  const cheaper = nextBand === null ? null : (() => {
    const maxHeight = heightAtDensity(weight, length, width, nextBand.minDensity);
    const requiredWeight = nextBand.minDensity * pieceCube;
    return {
      freightClass: nextBand.freightClass,
      requiredDensity: nextBand.minDensity,
      densityGap: nextBand.minDensity - density,
      // Null when no positive height reaches the band — the footprint alone
      // already holds too much air for this weight, so shortening cannot fix it.
      maxHeight,
      heightReduction: maxHeight === null ? null : height - maxHeight,
      requiredWeight,
      weightIncrease: requiredWeight - weight,
    };
  })();

  // The other direction, and the one that costs money unannounced: a carrier
  // dimensioner that finds the pallet taller than the bill of lading claims
  // re-rates it. Knowing the headroom before that happens is the difference
  // between packing to 46" on purpose and eating a re-class notice.
  //
  // Null in the bottom band, whose floor is zero density: there is no dearer
  // class to fall into and no positive height that would reach one.
  const dearer = dearerBand === null || band.minDensity <= 0 ? null : (() => {
    const maxHeight = heightAtDensity(weight, length, width, band.minDensity);
    const minWeight = band.minDensity * pieceCube;
    return {
      freightClass: dearerBand.freightClass,
      floorDensity: band.minDensity,
      densityHeadroom: density - band.minDensity,
      maxHeight,
      heightHeadroom: maxHeight === null ? null : maxHeight - height,
      minWeight,
      weightHeadroom: weight - minWeight,
    };
  })();

  return {
    length,
    width,
    height,
    weight,
    pieces,
    pieceCube,
    totalCube,
    totalWeight,
    density,
    freightClass: band.freightClass,
    bandMinimumDensity: band.minDensity,
    nextLowerClass: nextBand?.freightClass ?? null,
    nextLowerClassDensity: nextBand?.minDensity ?? null,
    // The density gap restated in the units a dock actually works in.
    // `cheaper` is what it would take to earn the next class down;
    // `dearer` is how much slack there is before losing the one you have.
    levers: { cheaper, dearer },
  };
}

levers.mjs.text:
// Turns the two levers `calc.mjs` computes into the sentences the page shows
// and the buttons copy.
//
// It lives beside the calculator rather than inside the page because both copy
// buttons and the result panel have to say the same thing. A repack target
// pasted into a warehouse email that disagreed with the panel it was read from
// is worse than no button at all.

const inches = n => `${n.toFixed(1)}″`;
const pounds = n => `${Math.round(n)} lb`;

// A bare 48x40 pallet is roughly 5-6 inches of deck and block before anything
// is loaded onto it, so a target height under that is arithmetic the dock
// cannot execute. Naming the limit is what keeps the lever from being a taunt.
export const PALLET_DECK_INCHES = 6;

// Under this much clearance the shipment is effectively sitting on its band
// floor, and the honest reading is "on the line", not a headroom figure.
export const ON_THE_LINE_INCHES = 0.5;

/**
 * @param {object} result the return value of `estimateFreightClass`
 * @returns {{cheaper: string, dearer: string, plain: string[]}}
 *   `cheaper`/`dearer` are HTML for the result panel (empty string when that
 *   lever does not exist, which the panel hides via `.lever:empty`); `plain` is
 *   the same content as plain-text lines for the clipboard.
 */
export function leverText(result) {
  const { cheaper, dearer } = result.levers;
  const lines = { cheaper: '', dearer: '', plain: [] };

  if (cheaper) {
    // Below a bare pallet's own height, shortening is not a move anyone can
    // make, so the sentence drops that half rather than printing a number the
    // reader would have to reject themselves.
    const tooShort = cheaper.maxHeight === null || cheaper.maxHeight < PALLET_DECK_INCHES;
    const height = tooShort ? '' : `pack to ${inches(cheaper.maxHeight)} (${inches(cheaper.heightReduction)} shorter)`;
    const weight = `put ${pounds(cheaper.requiredWeight)} per piece on it (${pounds(cheaper.weightIncrease)} more)`;
    const both = height ? `${height}, or ${weight}` : weight;
    lines.cheaper = `<b>Class ${cheaper.freightClass}</b> is one repack away: ${both}.`
      + (tooShort ? '<span class="warn">The height that would reach it is under a bare pallet, so weight is the only lever here.</span>' : '');
    lines.plain.push(`To reach class ${cheaper.freightClass}: ${both}.`);
  }

  if (dearer) {
    // Freight sitting within half an inch of its band floor is the expensive
    // case, and "0.0″ of headroom" is the wrong way to say so — it reads like a
    // rounding artefact rather than the warning it is. A tape measure and a
    // dimensioner disagree by more than this routinely.
    const onTheLine = dearer.heightHeadroom !== null && dearer.heightHeadroom < ON_THE_LINE_INCHES;
    const height = dearer.maxHeight === null
      ? ''
      : onTheLine
        ? ` above ${inches(dearer.maxHeight)}, which is where it already measures`
        : ` above ${inches(dearer.maxHeight)} — ${inches(dearer.heightHeadroom)} of headroom`;
    const sentence = `this freight re-rates${height}, or below ${pounds(dearer.minWeight)} per piece`;
    lines.dearer = `<b>Class ${dearer.freightClass}</b> is what a remeasure costs: ${sentence}.`
      + (onTheLine ? '<span class="warn">This is on the band line. A dimensioner that reads it a fraction taller bills the dearer class.</span>' : '');
    lines.plain.push(`Re-rates to class ${dearer.freightClass}${height}, or below ${pounds(dearer.minWeight)} per piece.`
      + (onTheLine ? ' On the band line — a dimensioner reading it a fraction taller bills the dearer class.' : ''));
  }

  return lines;
}

share.mjs.text:
// The pallet dimensions, weight, and piece count on this page are re-entered
// every time a shipper prices a new load. Losing them on a refresh, or having
// no way to hand the exact figures to a broker or a coworker pricing the same
// freight, is what this module fixes.
//
// The transform is pure and carries only the free numeric fields this
// calculator has -- no choices, no text, no rows. Nothing here is
// transmitted: the values travel in the URL fragment (`#...`), which a
// browser never sends to a server or a `Referer` header, so a copied link
// only ever goes where the sender pastes it.

export const NUMBER_FIELD_IDS = ['length', 'width', 'height', 'weight', 'pieces'];

// Only a finite, non-negative number is carried -- the same contract
// `estimateFreightClass` enforces on input, so a restored or shared value can
// never prefill a field the calculator would then reject.
function usableNumber(value) {
  if (value === '' || value === null || value === undefined) return null;
  const result = Number(value);
  if (!Number.isFinite(result) || result < 0) return null;
  return result;
}

// inputs object -> query string (no leading '?' or '#').
export function encodeInputs(inputs) {
  const params = new URLSearchParams();
  for (const id of NUMBER_FIELD_IDS) {
    const value = usableNumber(inputs?.[id]);
    if (value !== null) params.set(id, String(value));
  }
  return params.toString();
}

// query string -> inputs object. Accepts a bare string or one with a leading
// '?' or '#', so a caller can hand it `location.hash` or `location.search`
// untouched. Only the known numeric ids survive, and only if they parse.
export function decodeInputs(source) {
  if (typeof source !== 'string') return {};
  const params = new URLSearchParams(source.replace(/^[?#]/, ''));
  const inputs = {};
  for (const id of NUMBER_FIELD_IDS) {
    if (!params.has(id)) continue;
    const value = usableNumber(params.get(id));
    if (value !== null) inputs[id] = value;
  }
  return inputs;
}

usage.mjs.text:
const KEY = 'ltl-freight-class-usage';

export function usageAllowed() {
  try {
    if (localStorage.getItem('ltl-freight-class-usage-off') === '1') return false;
  } catch { return false; }
  return navigator.doNotTrack !== '1' && navigator.globalPrivacyControl !== true;
}

export function recordUsage(event) {
  if (!usageAllowed()) return;
  try {
    const current = JSON.parse(localStorage.getItem(KEY) || '{}');
    current[event] = (current[event] || 0) + 1;
    localStorage.setItem(KEY, JSON.stringify(current));
  } catch { /* Private browsing may deny local storage. */ }
}

export function clearUsage() {
  try {
    localStorage.removeItem(KEY);
    localStorage.setItem('ltl-freight-class-usage-off', '1');
  } catch { /* Private browsing may deny local storage. */ }
}
